## 5. Regression suite (route-level, real app, ephemeral port)

`apps/api/test/session-alias.test.ts` — boots the **real** `createApp()` on port `0`.

```ts
import { test, beforeEach, after } from 'node:test';
import assert from 'node:assert/strict';
import type { AddressInfo } from 'node:net';

process.env.SESSION_REGISTER_DELAY_MS = '100';

const { createApp } = await import('../src/app');
const { __resetStore } = await import('../src/orchestrator/session-store');

const app = createApp();
const server = app.listen(0);
await new Promise<void>((r) => server.once('listening', r));
const base = `http://127.0.0.1:${(server.address() as AddressInfo).port}/api`;

after(() => server.close());
beforeEach(() => __resetStore());
const wait = (ms: number) => new Promise((r) => setTimeout(r, ms));

async function createChatSession() {
  const res = await fetch(`${base}/chat`, { method: 'POST' });
  assert.equal(res.status, 202);
  return (await res.json()) as { decisionSessionId: string; streamId: string };
}
async function holdSeat(body: unknown) {
  const res = await fetch(`${base}/evacuation/hold-seat`, {
    method: 'POST',
    headers: { 'content-type': 'application/json' },
    body: JSON.stringify(body),
  });
  return { status: res.status, body: (await res.json()) as any };
}

test('streamId is accepted as a sessionId alias', async () => {
  const { streamId } = await createChatSession();
  await wait(250);
  const { status, body } = await holdSeat({ sessionId: streamId });
  assert.equal(status, 200, JSON.stringify(body));
  assert.ok(body.holdReference);
});

test('decisionSessionId still resolves', async () => {
  const { decisionSessionId } = await createChatSession();
  await wait(250);
  const { status, body } = await holdSeat({ sessionId: decisionSessionId });
  assert.equal(status, 200, JSON.stringify(body));
  assert.ok(body.holdReference);
});

test('unknown identifier returns the code-bearing envelope with no success key', async () => {
  const { status, body } = await holdSeat({ sessionId: 'does-not-exist' });
  assert.equal(status, 404);
  assert.equal(body.error?.code, 'SESSION_NOT_FOUND');
  assert.deepEqual(body.error?.details?.acceptedIdentifiers, ['decisionSessionId', 'streamId']);
  assert.equal(Object.prototype.hasOwnProperty.call(body, 'success'), false);
});

test('missing sessionId returns 400 INVALID_BODY with details.issues', async () => {
  const { status, body } = await holdSeat({});
  assert.equal(status, 400);
  assert.equal(body.error?.code, 'INVALID_BODY');
  assert.ok(Array.isArray(body.error?.details?.issues));
});
```

### RED proof

```bash
git stash push apps/api/src/orchestrator/session-store.ts \
              apps/api/src/routes/evacuation.ts
pnpm --filter api test -- session-alias
```

Observed before the fix — **exactly the two identifier/envelope tests fail**:

```
not ok 1 - streamId is accepted as a sessionId alias
not ok 3 - unknown identifier returns the code-bearing envelope with no success key
ok     2 - decisionSessionId still resolves          # after the registration wait
ok     4 - missing sessionId returns 400 INVALID_BODY
# pass 2  # fail 2
```

Restore and re-run: `git stash pop && pnpm --filter api test -- session-alias` → **4/4**.

